\section{Main Results}

Let $\Hm$ and $\Hn$ denote the $m$- and $n$-dimensional real hyperbolic spaces ($m, n \ge 2$), represented in upper half-space coordinates as 
\[
\Hm = \left\{ (x, y) \in \R^{m-1} \times (0, \infty) \right\}, \quad g_{\Hm} = \frac{|dx|^2 + dy^2}{y^2},
\]
and similarly for $\Hn$. Under this realization, the geometric boundary $\dHm$ is naturally identified with $\R^{m-1} \cup \{\infty\}$.

Our main result establishes the existence of harmonic extensions for Hölder continuous boundary maps into hyperbolic space, subject to a controlled vertical translation (an $\epsilon$-offset) in the final coordinate of the target space.

\begin{theorem}[$\epsilon$-Offset Boundary Value Problem for Harmonic Maps]
\label{thm:main_harmonic_extension}
Let $m, n \ge 2$ and $\alpha \in (0, 1]$. Let $f = (f_1, \dots, f_{n-1}): \R^{m-1} \to \R^{n-1}$ be an $\alpha$-Hölder continuous map, i.e., $f \in C^{0,\alpha}(\R^{m-1}; \R^{n-1})$. 

Then, for every $\epsilon > 0$, there exists a smooth harmonic map 
\[
u_\epsilon = (v_\epsilon, w_\epsilon) : \Hm \longrightarrow \Hn,
\]
where $v_\epsilon = (u_1, \dots, u_{n-1}) : \Hm \to \R^{n-1}$ and $w_\epsilon = u_n : \Hm \to (0, \infty)$, satisfying the boundary-value problem:
\begin{enumerate}
    \item[\mathrm{(i)}] \textbf{Harmonicity:} $u_\epsilon$ satisfies the hyperbolic harmonic map system
    \[
    \tau(u_\epsilon) \equiv \Delta_{\Hm} u_\epsilon^k + {}^{\Hn}\Gamma^{k}_{ij}(u_\epsilon) \nabla u_\epsilon^i \cdot \nabla u_\epsilon^j = 0, \quad \text{for } k = 1, \dots, n,
    \]
    where $\Delta_{\Hm} = y^2 \Delta_{\R^m} + (2-m)y \frac{\partial}{\partial y}$ is the Laplace--Beltrami operator on $\Hm$.

    \item[\mathrm{(ii)}] \textbf{Boundary Convergence with $\epsilon$-Offset:} For every $x \in \R^{m-1}$,
    \[
    \lim_{y \to 0^+} v_\epsilon(x, y) = f(x) \quad \text{and} \quad \lim_{y \to 0^+} w_\epsilon(x, y) = \epsilon,
    \]
    where the limits hold uniformly on compact subsets of $\R^{m-1}$.

    \item[\mathrm{(iii)}] \textbf{Regularity and Growth:} The components satisfy the asymptotic gradient bound
    \[
    |\nabla_{\Hm} u_\epsilon(x, y)|_{g_{\Hn}} \le C y^{\alpha}
    \]
    for a constant $C = C(m, n, \alpha, \|f\|_{C^{0,\alpha}}, \epsilon) > 0$ as $y \to 0^+$.
\end{enumerate}
\end{theorem}

\begin{remark}
Geometrically, condition \mathrm{(ii)} means that the boundary map $f: \dHm \to \dHn$ is continuously extended to a map whose boundary image is translated into the interior slice $\R^{n-1} \times \{\epsilon\} \subset \Hn$. As $\epsilon \to 0^+$, this family of harmonic maps $\{u_\epsilon\}_{\epsilon > 0}$ degenerates toward an ideal boundary harmonic extension $u: \Hm \to \Hn$.
\end{remark}

\begin{remark}
In explicit components, the harmonic system $\tau(u_\epsilon) = 0$ in condition \mathrm{(i)} reduces to the coupled non-linear PDE system:
\[
\begin{cases}
y^2 \Delta_{\R^m} v_\epsilon + (2-m)y \frac{\partial v_\epsilon}{\partial y} - \frac{2}{w_\epsilon} \left( \langle \nabla_{\R^m} v_\epsilon, \nabla_{\R^m} w_\epsilon \rangle + \frac{\partial v_\epsilon}{\partial y}\frac{\partial w_\epsilon}{\partial y} \right) = 0, \\[8pt]
y^2 \Delta_{\R^m} w_\epsilon + (2-m)y \frac{\partial w_\epsilon}{\partial y} + \frac{1}{w_\epsilon} \left( |\nabla_{\R^m} v_\epsilon|^2 + \left|\frac{\partial v_\epsilon}{\partial y}\right|^2 - |\nabla_{\R^m} w_\epsilon|^2 - \left|\frac{\partial w_\epsilon}{\partial y}\right|^2 \right) = 0.
\end{cases}
\]
The boundary conditions in Theorem \ref{thm:main_harmonic_extension} guarantee the uniform ellipticity of this system near $y = 0$ due to the strictly positive lower bound $w_\epsilon(x,y) \ge \epsilon$.
\end{remark}

