\begin{document}

\section*{Main Result}

Let $\Bm = \{x \in \mathbb{R}^m : |x| < 1\}$ denote the Poincaré ball model of the $m$-dimensional real hyperbolic space $\Hm$ ($m \ge 2$), equipped with the hyperbolic metric $g_{\mathbb{H}^m} = \frac{4|dx|^2}{(1-|x|^2)^2}$, and let $\Sm = \partial \Bm$ denote its ideal boundary at infinity. 

We establish the existence, uniqueness, and precise boundary asymptotics for harmonic maps taking prescribed Hölder continuous boundary data at infinity.

\begin{theorem}[Boundary Regularity and Existence of Harmonic Maps]
\label{thm:main_harmonic_extension}
Let $m, n \ge 2$, and let $\alpha \in (0, 1]$. Suppose $f: \Sm \to \Sn$ is an $\alpha$-Hölder continuous map with respect to the standard spherical metric, i.e., $f \in C^{0,\alpha}(\Sm, \Sn)$. 

Then, there exists a unique harmonic map $u: \Hm \to \Hn$ satisfying the asymptotic Dirichlet boundary condition 
\[
\lim_{r \to 1^-} u(r\theta) = f(\theta) \quad \text{uniformly for all } \theta \in \Sm.
\]
Furthermore, $u$ satisfies the following quantitative boundary properties:
\begin{enumerate}
    \item \textbf{Global Hölder Continuity:} Viewed as a map on the closed Poincaré ball, $u \in C^{0,\beta}(\dbar{}^m, \dbar{}^n)$ for any $\beta < \min\{\alpha, m-1\}$. In particular, there exists a constant $C = C(m, n, \alpha, \|f\|_{C^{0,\alpha}}) > 0$ such that for all $x, y \in \dbar{}^m$,
    \[
    |u(x) - u(y)| \le C |x - y|^\beta.
    \]

    \item \textbf{Hyperbolic Asymptotic Decay:} Let $d_{\Hn}(\cdot, \cdot)$ denote the geodesic distance in $\Hn$. For any extension $\tilde{f} \in C^{0,\alpha}(\dbar{}^m, \dbar{}^n)$ of $f$, there exist constants $C > 0$ and $\gamma = \gamma(m, \alpha) > 0$ such that for all $z \in \Bm$,
    \[
    d_{\Hn}\left(u(z), \tilde{f}(z)\right) \le C (1 - |z|)^\gamma \exp\left( C (1 - |z|)^{-\alpha} \right).
    \]
\end{enumerate}
\end{theorem}

\begin{remark}
The uniqueness in Theorem~\ref{thm:main_harmonic_extension} holds within the class of proper continuous extensions $u \in C^0(\dbar{}^m, \dbar{}^n)$. The Hölder exponent $\beta$ up to the boundary is sharp in terms of the decay rates governed by the spectral gap of the Laplacian on $\Hm$.
\end{remark}

